input.content:
module default {
    scalar type ArticleStatus extending enum<draft, published, archived>;

    type Article {
        required property slug -> str {
            constraint exclusive;
        }
        required property title -> str;
        required property summary -> str;
        required property body -> str;
        required property status -> ArticleStatus;
        property tags -> multi str;

        index fts::index on ((
            fts::with_options(
                .title,
                language := fts::Language.eng,
                weight_category := fts::Weight.A,
            ),
            fts::with_options(
                .summary,
                language := fts::Language.eng,
                weight_category := fts::Weight.B,
            ),
            fts::with_options(
                .body,
                language := fts::Language.eng,
                weight_category := fts::Weight.C,
            )
        ));
    }
}

output.content:
CREATE MIGRATION m1rmia6bdz3xhcjlpevxkk3lnbsttw7asts2szocbkcvuvp4l2vhwq
    ONTO initial
{
  CREATE SCALAR TYPE default::ArticleStatus EXTENDING enum<draft, published, archived>;
  CREATE TYPE default::Article {
      CREATE REQUIRED PROPERTY body: std::str;
      CREATE REQUIRED PROPERTY summary: std::str;
      CREATE REQUIRED PROPERTY title: std::str;
      CREATE INDEX std::fts::index ON ((std::fts::with_options(.title, language := std::fts::Language.eng, weight_category := std::fts::Weight.A), std::fts::with_options(.summary, language := std::fts::Language.eng, weight_category := std::fts::Weight.B), std::fts::with_options(.body, language := std::fts::Language.eng, weight_category := std::fts::Weight.C)));
      CREATE REQUIRED PROPERTY slug: std::str {
          CREATE CONSTRAINT std::exclusive;
      };
      CREATE REQUIRED PROPERTY status: default::ArticleStatus;
      CREATE MULTI PROPERTY tags: std::str;
  };
};

input.command:
cd /home/user/kbsearch && gel query "
insert Article {
    slug := 'test-1',
    title := 'Test article about policies',
    summary := 'A summary mentioning cluster',
    body := 'The body discusses the warehouse and cluster provisioning',
    status := <ArticleStatus>'published',
    tags := {'ops', 'database'}
} unless conflict on .slug else (
    update Article set {
        title := 'Test article about policies',
        summary := 'A summary mentioning cluster',
        body := 'The body discusses the warehouse and cluster provisioning',
        status := <ArticleStatus>'published',
        tags := {'ops', 'database'}
    }
);
" 2>&1; echo "---EXIT: $?"

cd /home/user/kbsearch && gel query "
insert Article {
    slug := 'test-title-only',
    title := 'uniqueword article',
    summary := 'different content here',
    body := 'more different text entirely',
    status := <ArticleStatus>'published',
} unless conflict on .slug else (
    update Article set {
        title := 'uniqueword article',
        summary := 'different content here',
        body := 'more different text entirely',
        status := <ArticleStatus>'published',
    }
);
" 2>&1; echo "---"
gel query "
insert Article {
    slug := 'test-summary-only',
    title := 'some other title',
    summary := 'uniqueword appears in summary',
    body := 'body text is different',
    status := <ArticleStatus>'published',
} unless conflict on .slug else (
    update Article set {
        title := 'some other title',
        summary := 'uniqueword appears in summary',
        body := 'body text is different',
        status := <ArticleStatus>'published',
    }
);
" 2>&1; echo "---"
gel query "
insert Article {
    slug := 'test-body-only',
    title := 'completely different title',
    summary := 'a different summary',
    body := 'uniqueword shows up in body',
    status := <ArticleStatus>'published',
} unless conflict on .slug else (
    update Article set {
        title := 'completely different title',
        summary := 'a different summary',
        body := 'uniqueword shows up in body',
        status := <ArticleStatus>'published',
    }
);
" 2>&1; echo "---EXIT: $?"

cd /home/user/kbsearch && gel query "
with res := (select fts::search(Article, 'uniqueword', language := 'eng'))
select res.object { slug, score := res.score }
filter res.score > 0
order by res.score desc;
" 2>&1; echo "---EXIT: $?"

output.output:
{"slug": "test-title-only", "score": 0.6079271}
{"slug": "test-summary-only", "score": 0.30396354}
{"slug": "test-body-only", "score": 0.15198177}
---EXIT: 0

