cd /home/user/kbsearch && gel query "
insert Article {
    slug := 'test-two-terms-title',
    title := 'uniqueword secondword article',
    summary := 'different content here',
    body := 'more different text entirely',
    status := <ArticleStatus>'published',
} unless conflict on .slug else (
    update Article set { title := 'uniqueword secondword article', summary := 'different content here', body := 'more different text entirely', status := <ArticleStatus>'published' }
);
" 2>&1; echo "--- two terms in title ---"
gel query "
with res := (select fts::search(Article, 'uniqueword secondword', language := 'eng'))
select res.object { slug, score := res.score }
filter res.score > 0
order by res.score desc;
" 2>&1; echo "--- morphological: policies -> policy ---"
gel query "
with res := (select fts::search(Article, 'policies', language := 'eng'))
select res.object { slug, score := res.score }
filter res.score > 0
order by res.score desc;
" 2>&1; echo "---EXIT: $?"

